from concurrent.futures import ThreadPoolExecutor

import pytest

DEFAULT_WORKERS: int = 4  # thread pool size; the result must not depend on this value


def parity(x: int) -> int:
    """Return x % 2, so 0 for even and 1 for odd (Python semantics for negatives)."""
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return parity(x) for each x in xs, computed in a thread pool.

    The output preserves input order and is identical for any worker count.
    """
    with ThreadPoolExecutor(max_workers=DEFAULT_WORKERS) as pool:
        return list(pool.map(parity, xs))


def test_parity_basic() -> None:
    assert parity(0) == 0
    assert parity(1) == 1
    assert parity(6) == 0
    assert parity(7) == 1


def test_parity_negative() -> None:
    assert parity(-1) == 1
    assert parity(-2) == 0


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([5]) == [1]
    assert parities([8]) == [0]


def test_parities_preserves_order() -> None:
    xs = [3, 2, 1, 0, 9, 8, 7, 6]
    assert parities(xs) == [1, 0, 1, 0, 1, 0, 1, 0]


def test_parities_matches_sequential_on_large_input() -> None:
    xs = list(range(-500, 500))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_mixed_negative_and_positive() -> None:
    assert parities([-3, -2, 0, 5]) == [1, 0, 0, 1]


@pytest.mark.parametrize("n", [1, 2, 3, 16, 17])
def test_parities_length_matches_input(n: int) -> None:
    xs = list(range(n))
    assert len(parities(xs)) == n
